```javascript
/**
 * TokenBucket Rate Limiting Implementation
 */

function now() {
  return Date.now();
}

class TokenBucket {
  constructor({ capacity, refillPerSecond, now = now }) {
    if (!Number.isFinite(capacity) || capacity <= 0) {
      throw new RangeError('Capacity must be a positive finite number');
    }
    if (typeof refillPerSecond !== 'number' || refillPerSecond < 0) {
      throw new RangeError('Refill per second must be a non-negative number');
    }

    this.now = now;
    this.capacity = capacity;
    this.refillPerSecond = refillPerSecond;

    // Start full as requested by the spec
    this._tokens = capacity;
    this._lastUpdated = this.now();
  }

  /**
   * Updates token count based on elapsed time since last update.
   */
  _update() {
    const current = this.now();
    if (current <= this._lastUpdated) return;

    const deltaSeconds = (current - this._lastUpdated) / 1000;
    this._tokens += deltaSeconds * this.refillPerSecond;
    this._tokens = Math.min(this._tokens, this.capacity);
    this._lastUpdated = current;
  }

  /**
   * Returns the number of tokens currently in the bucket (can be fractional).
   */
  available() {
    this._update();
    return this._tokens;
  }

  /**
   * Try to take n tokens. Deduct if available, otherwise return false without deducting anything.
   */
  tryTake(n = 1) {
    if (!Number.isFinite(n) || n <= 0) throw new RangeError('Amount must be a positive finite number');

    this._update();
    if (this._tokens >= n) {
      this._tokens -= n;
      return true;
    }
    return false;
  }

  /**
   * How many milliseconds until at least n tokens are available.
   */
  msUntil(n = 1) {
    if (!Number.isFinite(n) || n <= 0) throw new RangeError('Amount must be a positive finite number');

    this._update();
    const needed = n - this._tokens;

    // Edge cases where it can never be satisfied
    if (needed > 0 && n > this.capacity) return Infinity;
    if (needed > 0 && this.refillPerSecond <= 0) return Infinity;

    // If already enough, no wait needed
    if (needed <= 0) return 0;

    // How many seconds to fill the deficit at a constant rate
    const seconds = needed / this.refillPerSecond;
    return Math.ceil(seconds * 1000);
  }
}

module.exports = { TokenBucket };
```

